import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { writeFileSync,readFileSync } from 'node:fs';
import { setTimeout as delay } from 'node:timers/promises';
const candidate=execFileSync('git',['rev-parse','HEAD'],{encoding:'utf8'}).trim();
assert.equal(candidate,'cad38a178d19d42d4be1cb542ccd5e67be54896a');
assert.equal(typeof globalThis.gc,'function');
const report={sourceCommit:candidate,node:process.version,versions:process.versions,seed:20261004,purpose:'Fresh-process GC control separates collectible harness/application heap from PJS-owned logical bookkeeping and allocator high-water',before:process.memoryUsage(),passed:false};
await import('../../scripts/rc/soak.mjs');
const path=process.argv.find(a=>a.startsWith('--output=')).slice('--output='.length);
const soak=JSON.parse(readFileSync(path));assert.equal(soak.passed,true);
report.afterSoak=process.memoryUsage();report.resourcesBeforeGC=process.getActiveResourcesInfo();
globalThis.gc();await delay(0);globalThis.gc();await delay(0);
report.afterGC=process.memoryUsage();report.resourcesAfterGC=process.getActiveResourcesInfo();
assert.ok(!report.resourcesAfterGC.some(x=>['Timeout','MessagePort'].includes(x)));
assert.ok(soak.terminals.every(t=>t.tasks===0&&t.operations===0&&t.reservations===0&&t.executions===0&&t.creditOperations===0&&t.busy===0&&t.liveWorkers===0&&t.reservedBytes===0&&t.buffers===0));
report.soakCounts=soak.operationCounts;report.passed=true;
writeFileSync('.node-tools/rc1/memory-control.json',JSON.stringify(report,null,2)+'\n',{flag:'wx'});
console.log(JSON.stringify(report));
